    def dfs(node, visited, path):
        if node in visited:
            return False
        visited.add(node)
        path.append(node)

        for neighbor in graph[node]:
            if not dfs(neighbor, visited, path):
                return False

        path.pop()
        visited.remove(node)
        return True

    max_width = 0
    for i in range(n):
        for j in range(i + 1, n):
            if (i, j) in edges:
                continue

            visited = set()
            path = []
            if dfs(j, visited, path):
                max_width = max(max_width, len(path))

    return max_width

