        n = len(G)
        edges = [(u, v) for u in range(n//2) for v in range(n//2, n)]
        A = [[0] * n for _ in range(n)]
        B = [[0] * n for _ in range(n)]
        for u, v in edges:
            A[u][v] = 1
            B[v][u] = 1
        H = [A[i] + B[i] for i in range(n)]
        return gaussian_elimination(H)

    def minimal_hodge_arcs(A, B, edges):
