                            H[i][j] += Fraction(1)
                            H[j][i] += Fraction(1)
        return H

    def min_quaternionic_norm(H):
        n = len(H)
        I = [[Fraction(1) if i == j else Fraction(0) for j in range(n)] for i in range(n)]
        A = [H[i] + I[i] for i in range(n)]
