import random
import math
from fractions import Fraction

def generate_random_instance(n, m):
    instance = []
    for _ in range(m):
        clause = [random.choice([-1, 1]) * (i + 1) for i in range(n)]
        instance.append(clause)
    return instance

def compute_p_adic_valuation(instance):
    valuation = float('inf')
    for clause in instance:
        product = 1
        for literal in clause:
            if literal == -1:
                product *= -1
            elif literal == 1:
                continue
            else:
                raise ValueError("Invalid literal in clause")
        valuation = min(valuation, abs(product))
    return valuation

def calculate_entropy(clause_set):
    n = len(clause_set)
    counts = [0] * (n + 1)
    for clause in clause_set:
        counts[len(clause)] += 1
    entropy = 0.0
    for count in counts:
        if count > 0:
            p = Fraction(count, n)
            entropy -= p * math.log2(p)
    return entropy

def run_trial(seed: int) -> dict:
    random.seed(seed)
    results = []
    for n in [5, 10, 15, 20, 30, 40]:
        m = random.randint(2*n, 3*n)
