        n = len(G)
        literals = [f"x{i}" for i in range(n)]
        clauses = []
        for i in range(n):
            clause = [literals[i]]
            for j in range(n):
                if G[i][j]:
                    clause.append(f"~{literals[j]}")
            clauses.append(clause)
            for j in range(i+1, n):
                for k in range(j+1, n):
