                        clauses.append([f"~{literals[i]}", f"~{literals[j]}", literals[k]])
        return clauses

    def eigenvalues(G):
        n = len(G)
        A = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if G[i][j]:
                    A[i][j] = 1
        det_A = determinant(A)
        if det_A == 0:
            return None
        eigenvals = []
        for k in range(1, n+1):
            I = [[0] * n for _ in range(n)]
            for i in range(n):
                I[i][i] = 1
            A_k = [[A[i][j]**k for j in range(n)] for i in range(n)]
            det_A_k = determinant(A_k)
            if det_A_k == 0:
                eigenvals.append(k)
        return eigenvals

    def m_order(eigenvals):
        if not eigenvals:
            return None
        min_order = float('inf')
        for val in eigenvals:
            order = sum(1 for e in eigenvals if abs(e - val) < 1e-6)
            if order < min_order:
                min_order = order
        return min_order

    def resolution_proof_width(clauses):
        n = len(clauses)
        width = max(len(c) for c in clauses)
        return width

