            "metric_value": None,
            "instances_tested": 1,
            "n_max": n,
            "conjecture_holds": False,
            "counterexample": "graph_not_d_regular"
        }

    clauses = tseitin_formula(G)
    eigenvals = eigenvalues(G)
    if not eigenvals:
        return {
            "metric_name": "m_order",
            "metric_value": None,
            "instances_tested": 1,
            "n_max": n,
            "conjecture_holds": False,
            "counterexample": "eigenvalue_computation_failed"
        }

    m = m_order(eigenvals)
    w = resolution_proof_width(clauses)

    return {
        "metric_name": "m_order",
        "metric_value": m,
        "instances_tested": 1,
        "n_max": n,
