        n = len(cnf[0])
        code_matrix = [[0] * (2**n) for _ in range(n)]
        for i, clause in enumerate(cnf):
            for j in range(2**n):
                if all(x * (j >> abs(var) & 1) >= 0 for x, var in zip(clause, range(n))):
                    code_matrix[i][j] = 1
        return code_matrix

