        n = len(cnf[0])
        code_matrix = compute_linear_code(cnf)
        order = 1
        for i in range(n):
            for j in range(i + 1, n):
                if all(code_matrix[i][k] == code_matrix[j][k] for k in range(2**n)):
                    order *= 2
        return order

