import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_cnf(n, m):
        cnf = []
        for _ in range(m):
            clause = [random.randint(1, n), -random.randint(1, n)]
            cnf.append(clause)
        return cnf

    def gaussian_elimination(matrix):
        rows, cols = len(matrix), len(matrix[0])
        rank = 0
        for i in range(cols):
            max_row = rank
            for j in range(rank, rows):
                if abs(matrix[j][i]) > abs(matrix[max_row][i]):
                    max_row = j
            if matrix[max_row][i] == 0:
                continue
            matrix[rank], matrix[max_row] = matrix[max_row], matrix[rank]
            for j in range(rows):
                if j != rank:
                    factor = -matrix[j][i] / matrix[rank][i]
                    for k in range(cols):
                        matrix[j][k] += factor * matrix[rank][k]
            rank += 1
        return rank

    def min_order(cnf):
        n = len(cnf)
        identity_matrix = [[0] * n for _ in range(n)]
        for i in range(n):
            identity_matrix[i][i] = 1

        for clause in cnf:
            a, b = abs(clause[0]), abs(clause[1])
            if a == b:
                continue
            matrix = [[0] * n for _ in range(n)]
            for i in range(n):
                for j in range(n):
                    if (i + 1) in clause and (j + 1) in clause:
                        matrix[i][j] = 1
            rank = gaussian_elimination(matrix)
        return rank

    def monotone_width(cnf):
        n = len(cnf)
        width = [0] * (n + 1)
        for i in range(n):
            for j in range(i + 1, n):
                if any(lit in cnf[i] and -lit in cnf[j] for lit in range(1, n + 1)):
                    width[min(i, j)] += 1
        return max(width)

    n = random.randint(5, 40)
    m = random.randint(n, n * 2)
    cnf = generate_cnf(n, m)
    order = min_order(cnf)
    width = monotone_width(cnf)

    return {
