            if lit.startswith('~'):
                lits_false.add(lit[1:])
            else:
                lits_true.add(lit)

            if solve(lits_true, lits_false):
                break

        hmranks.append(len(lits_true))
        widths.append(len(clauses))

    mean_hmrank = sum(hmranks) / len(hmranks)
