        n = len(cnf[0])
        poly = [[0] * (1 << n) for _ in range(len(cnf))]
        for i, clause in enumerate(cnf):
            mask = 0
            for lit in clause:
                if lit > 0:
                    mask |= 1 << (lit - 1)
                else:
                    mask |= 1 << (-lit - 1)
            poly[i][mask] = 1
        return poly

