    ratio = (math.log(n, 2) ** 2) / width
    return {
        "metric_name": "log(n)^2 / w(φ)",
        "metric_value": ratio,
        "instances_tested": 1,
        "n_max": n,
        "conjecture_holds": ratio <= order,
