        while queue:
            literal = queue.pop(0)
            if literal < 0:
                continue
            for i, clause in enumerate(clauses):
                if literal in clause and -literal in clause:
                    clauses[i] = [l for l in clause if l != literal and l != -literal]
                    if not clauses[i]:
