import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def gaussian_elimination(A):
        n = len(A)
        for i in range(n):
            max_row = i
            for j in range(i+1, n):
                if abs(A[j][i]) > abs(A[max_row][i]):
                    max_row = j
            A[i], A[max_row] = A[max_row], A[i]
            factor = A[i][i]
            for j in range(i, n + 1):
                A[i][j] /= factor
            for j in range(n):
                if j != i:
                    factor = A[j][i]
                    for k in range(i, n + 1):
                        A[j][k] -= factor * A[i][k]
        return A

    def matrix_multiplication(A, B):
        m = len(A)
        p = len(B[0])
        q = len(B)
        C = [[0 for _ in range(p)] for _ in range(m)]
        for i in range(m):
            for j in range(p):
                for k in range(q):
                    C[i][j] += A[i][k] * B[k][j]
        return C

    def determinant(A):
        n = len(A)
        if n == 1:
            return A[0][0]
        det = 0
        sign = 1
        for i in range(n):
            minor = [row[:i] + row[i+1:] for row in A[1:]]
            det += sign * A[0][i] * determinant(minor)
            sign *= -1
        return det

    def geometric_galois_group_size(A):
        n = len(A)
        if n == 0:
            return 1
        rank = sum(1 for row in gaussian_elimination(A) if any(row))
        return math.factorial(n) // (math.factorial(rank) * math.factorial(n - rank))

