        g_ent = geometric_entropy(graph)
        comm_matrix = communication_complexity_matrix(graph)
        rnk = rank(comm_matrix)

        if rnk == 0:
            continue

        results.append({
            "n": n,
            "g_ent": g_ent,
            "rnk": rnk
        })

    if not results:
        return {
            "metric_name": "geometric_entropy",
            "metric_value": None,
            "instances_tested": 0,
            "n_max": 0,
            "conjecture_holds": False,
